import{z as s,x as l,o as A,c as d,q as B,j as n,D as e,d as E,s as o,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"公司行动处理的深入","description":"","frontmatter":{"title":"公司行动处理的深入","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/de-corporate-action-deep.md","filePath":"quant/de-corporate-action-deep.md","lastUpdated":1791063341000}'),p={name:"quant/de-corporate-action-deep.md"};function D(h,a,u,c,C,m){const r=l("Mermaid");return A(),d("div",null,[a[2]||(a[2]=B('<h1 id="公司行动处理的深入" tabindex="-1">公司行动处理的深入 <a class="header-anchor" href="#公司行动处理的深入" aria-label="Permalink to &quot;公司行动处理的深入&quot;">​</a></h1><div class="epigraph"><p>公司行动不是「修正错误的价格」，是同一只证券换了计数单位；处理它的全部难点在于，哪一天、按什么比例、对哪几张表生效。</p><footer>—— 据 CRSP 调整因子文档口径；A 股除权除息实务整理</footer></div><p><a href="/quant/de-marketdata-cleaning">上一课</a>把单日内的字节洗成带账目的序列；但序列在日界上仍会断裂——除息日开盘价跳低、送转日股数翻倍、退市日收益终止，这些不是坏数据，是证券换了计数单位。<a href="/quant/corporate-actions">分红、拆股与复权</a>立过基础口径：不复权无法算持有收益。本课写深钻的三个问题：复权有几种、各喂哪类信号；一次行动要联动几张表；调整因子为什么必须是事件链而不是就地改价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一次公司行动同时打在多张表上，只修价格是第一类错。<span class="marginnote">常见误区：初学者容易把除息日开盘的跳低当成暴跌。股票 10 元、每股分红 1 元，除息日开盘参考价就是 9 元左右——那 1 元进了你的口袋，不是蒸发。把这种「计数单位换了」的缺口当价格变动算进收益，是公司行动数据里最常见的第一类错。</span>分红与送转改价格与股数，配股改价格与出资人，分拆与合股还会改代码与成分资格，退市决定收益序列在哪里终止——漏掉任何一张表，市值、换手、EPS 与成分资格就各说各话。第二类错是比例语义：现金分红按每股金额除息，送转按比例除权，把 A 股「10 转 10」当成分红，除权缺口会被算成收益<span class="marginnote">数字实例：「10 转 10」是每 10 股送转 10 股，持股翻倍、股价约减半，总市值不变；若误当现金分红，复权程序会把那 50% 的价格缺口算成一笔巨额正收益，整条历史收益凭空多出近一倍。比例语义错一档，程序不报错，只留下静默的系统性偏移。</span>；反向拆细与合股的比例小于 \\(1\\)，符号错一行，整条历史反向。第三类错在复权口径：供应商调整因子、交易所除权参考价、自算因子常有分位级差异，而收益率要求因子连续，价差信号要求绝对水平，两种用途共用一条复权链必有一边错。</p><h3 id="复权的两种用途分开" tabindex="-1">复权的两种用途分开 <a class="header-anchor" href="#复权的两种用途分开" aria-label="Permalink to &quot;复权的两种用途分开&quot;">​</a></h3><p>后复权（自上市日起向前累乘因子）保持历史值不随未来行动改变，适合算收益与累积净值；前复权（把最新价锚定为当前真实价）直观，但每次分红都改写全部历史——研究库可以存，特征库不该依赖它。喂给<a href="/quant/cs-rank-features">特征：滞后、截面 rank</a> 的价格特征，应以后复权或未复权加显式调整项为准，让「哪些天被调整过」可查。</p><p><span class="marginnote">复权因子链要含退市与停牌：最后的除息发生在退市公告之后时，因子链若在退市日截断，最后一段持有收益就凭空少一笔——这正是<a href="/quant/survivorship-bias">幸存者偏差</a>在数据层的样子。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把公司行动做成事件链引擎，三条规则。<strong>一，事件先行</strong>：公告日、除权日、支付日各入一行，特征按公告日可知、价格按除权日生效——与<a href="/quant/point-in-time">时点基本面</a>的两枚时间戳同构。<strong>二，因子独立存储</strong>：调整因子是带生效区间的独立序列，价格表保持未复权原貌，复权在查询时按需合成。<strong>三，多表联动</strong>：一次行动在同一事务里更新价格因子、股本历史、成分资格与代码映射四张表，<a href="/quant/index-constituents-history">指数成分历史</a>的口径在这里被消费。验收用不变量：除权日按因子调整后的收益率应与公告比例一致，并逐股票抽五次历史行动手工对账。</p>',10)),(A(),n(i,null,{default:e(()=>[o(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ANN%5B%22%E5%85%AC%E5%91%8A%E6%97%A5%EF%BC%9A%E4%BF%A1%E6%81%AF%E5%8F%AF%E7%9F%A5%22%5D%20--%3E%20EFF%5B%22%E9%99%A4%E6%9D%83%E6%97%A5%EF%BC%9A%E5%9B%A0%E5%AD%90%E7%94%9F%E6%95%88%22%5D%0A%20%20EFF%20--%3E%20F%5B%22%E5%9B%A0%E5%AD%90%E8%A1%A8%EF%BC%9A%E5%B8%A6%E7%94%9F%E6%95%88%E5%8C%BA%E9%97%B4%E7%9A%84%E6%96%B0%E7%89%88%E6%9C%AC%22%5D%0A%20%20F%20--%3E%20P%5B%22%E6%9C%AA%E5%A4%8D%E6%9D%83%E4%BB%B7%E6%A0%BC%E8%A1%A8%E4%BF%9D%E6%8C%81%E5%8E%9F%E8%B2%8C%22%5D%0A%20%20F%20--%3E%20S%5B%22%E8%82%A1%E6%9C%AC%E5%8E%86%E5%8F%B2%22%5D%0A%20%20F%20--%3E%20C%5B%22%E6%88%90%E5%88%86%E8%B5%84%E6%A0%BC%E4%B8%8E%E4%BB%A3%E7%A0%81%E6%98%A0%E5%B0%84%22%5D%0A%20%20P%20--%3E%20Q%5B%22%E6%9F%A5%E8%AF%A2%E6%97%B6%E6%8C%89%E9%9C%80%E5%90%88%E6%88%90%E5%A4%8D%E6%9D%83%E4%BB%B7%22%5D%0A%20%20S%20--%3E%20Q%0A%20%20C%20--%3E%20Q%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[E("因子独立存储之所以是核心，在于它把「历史」与「我们对历史的当前理解」分开：价格表是观测，因子表是解释，解释可修订而观测不动。"),t("span",{class:"marginnote"},"直觉类比：未复权价格表像实验室的原始记录本，调整因子像夹在本子里的一叠勘误卡——新分红来了就多插一张卡，原始记录一个字不动；前复权则是每次都用橡皮把整本记录重抄一遍，抄完还跟你保证「这就是当时的数据」。"),E("这直接决定下游成本——用前复权价存库，每次分红触发全表改写，十年历史的缓存、特征与回测结果全部失效；用因子链，改写只落在一张小表的新版本里，下游按需重建。")],-1)),(A(),n(i,null,{default:e(()=>[o(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20FWD%5B%22%E5%89%8D%E5%A4%8D%E6%9D%83%3A%20%E6%9C%80%E6%96%B0%E4%BB%B7%E9%94%9A%E5%AE%9A%22%5D%0A%20%20%20%20A1%5B%22%E4%BB%8A%E5%A4%A9%E6%96%B0%E5%85%AC%E5%91%8A%E4%B8%80%E6%AC%A1%E5%88%86%E7%BA%A2%22%5D%20--%3E%20A2%5B%22%E6%95%B4%E6%9D%A1%E5%8E%86%E5%8F%B2%E4%BB%B7%E6%A0%BC%E5%85%A8%E9%83%A8%E9%87%8D%E5%86%99%22%5D%0A%20%20%20%20A2%20--%3E%20A3%5B%22%E5%8D%81%E5%B9%B4%E7%BC%93%E5%AD%98%20%2F%20%E7%89%B9%E5%BE%81%20%2F%20%E5%9B%9E%E6%B5%8B%E7%BB%93%E6%9E%9C%E5%A4%B1%E6%95%88%22%5D%0A%20%20end%0A%20%20subgraph%20BWD%5B%22%E5%90%8E%E5%A4%8D%E6%9D%83%3A%20%E5%9B%A0%E5%AD%90%E9%93%BE%E8%BF%BD%E5%8A%A0%22%5D%0A%20%20%20%20B1%5B%22%E5%90%8C%E4%B8%80%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20B2%5B%22%E5%9B%A0%E5%AD%90%E8%A1%A8%E5%8F%AA%E5%8A%A0%E4%B8%80%E4%B8%AA%E6%96%B0%E7%94%9F%E6%95%88%E5%8C%BA%E9%97%B4%22%5D%0A%20%20%20%20B2%20--%3E%20B3%5B%22%E5%8E%86%E5%8F%B2%E8%A7%82%E6%B5%8B%E4%B8%8D%E5%8A%A8%2C%20%E4%B8%8B%E6%B8%B8%E6%8C%89%E9%9C%80%E9%87%8D%E7%AE%97%22%5D%0A%20%20end%0A%20%20A3%20-.%20%22%E6%94%B9%E7%94%A8%E5%9B%A0%E5%AD%90%E9%93%BE%E5%90%8E%22%20.-%3E%20B1%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p>比例语义也由此可查：每个因子的推导都挂在事件上，审计一条因子就是审计一次行动，而不是信任供应商的黑盒乘数。错误在这里的形态是静默的：比例错一档不会让程序崩溃，只会让因子在除息日附近系统性偏移，回测里表现为「除息季节性」，实为数据病灶。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重讲基础复权公式，见<a href="/quant/corporate-actions">分红、拆股与复权</a>；不处理期权与可转债的调整，那是衍生品口径。因子链也覆盖不了极端事件：破产清算、私有化要约、缩股换代码需要人工事件表兜底。供应商因子与自算因子要定期对账；因子表同样是数据，进版本化，由下一课接管。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一次公司行动联动价格因子、股本、成分、代码四张表，只修价格必错。</li><li>现金分红按金额、送转按比例，比例语义错一档是静默的系统性偏移。</li><li>后复权喂收益与特征，前复权只做展示，特征库不依赖会改写历史的前复权。</li><li>因子独立成带生效区间的版本序列，价格表保持原貌，改写不触历史。</li><li>出处：CRSP 调整因子文档口径；A 股除权除息实务；站内<a href="/quant/corporate-actions">分红、拆股与复权</a>、<a href="/quant/point-in-time">时点基本面</a>。</li></ul>',5))])}const q=s(p,[["render",D]]);export{F as __pageData,q as default};
